func (u *ModerationReportUpsertBulk) UpdateNewValues() *ModerationReportUpsertBulk {
	u.create.conflict = append(u.create.conflict, sql.ResolveWithNewValues())
	u.create.conflict = append(u.create.conflict, sql.ResolveWith(func(s *sql.UpdateSet) {
		for _, b := range u.create.builders {
			if _, exists := b.mutation.ID(); exists {
				s.SetIgnore(moderationreport.FieldID)
			}
			if _, exists := b.mutation.SiteID(); exists {
				s.SetIgnore(moderationreport.FieldSiteID)
			}
			if _, exists := b.mutation.ReporterID(); exists {
				s.SetIgnore(moderationreport.FieldReporterID)
			}
			if _, exists := b.mutation.TargetType(); exists {
				s.SetIgnore(moderationreport.FieldTargetType)
			}
			if _, exists := b.mutation.TargetID(); exists {
				s.SetIgnore(moderationreport.FieldTargetID)
			}
			if _, exists := b.mutation.CreatedAt(); exists {
				s.SetIgnore(moderationreport.FieldCreatedAt)
			}
		}
	}))
	return u
}

